create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(char_length(username) between 3 and 20),avatar_url text,created_at timestamptz not null default now());
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),code text not null unique check(code ~ '^[A-Z0-9]{6,8}$'),owner_id uuid not null references auth.users(id) on delete restrict,name text not null check(char_length(name) between 2 and 40),is_private boolean not null default false,status text not null default 'open' check(status in ('open','playing','closed')),max_players int not null default 10 check(max_players between 2 and 16),created_at timestamptz not null default now(),last_activity_at timestamptz not null default now());
create table if not exists public.room_members(room_id uuid not null references public.rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'player' check(role in ('owner','moderator','player')),joined_at timestamptz not null default now(),primary key(room_id,user_id));
alter table public.profiles enable row level security;alter table public.rooms enable row level security;alter table public.room_members enable row level security;
create policy "profiles readable by authenticated users" on public.profiles for select to authenticated using(true);
create policy "users create own profile" on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy "users update own profile" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "authenticated users view public open rooms" on public.rooms for select to authenticated using(is_private=false and status<>'closed');
create policy "owners view their rooms" on public.rooms for select to authenticated using(owner_id=auth.uid());
create policy "members view their memberships" on public.room_members for select to authenticated using(user_id=auth.uid());
-- Mutations intentionally withheld until authenticated RPCs and transactional authorization are implemented.